fn load_config(verbose: bool, format: OutputFormat) -> Result<(Option<OrandaConfig>, String), i32> {
    let path = Path::new("./oranda.json");
    if !path.exists() {
        print_debug("No config found, using default values", verbose, format);
        return Ok((None, "public".to_string()));
    }
    // file exists, try parse
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            // should not happen
            eprintln!("Failed to read config: {}", e);
            std::process::exit(255);
        }
    };
    // Try parse with TopLevel to get proper errors for unknown fields etc.
    // First, try to parse as serde_json::Value to get line/col errors? Use serde_json from_str, then check error.
    // We'll attempt to deserialize to TopLevel, which will give errors for unknown fields and invalid types.
    let result: Result<TopLevel, serde_json::Error> = serde_json::from_str(&content);
    match result {
        Ok(top) => {
            // Need dist_dir from build
            let dist = top.build.and_then(|b| b.dist_dir).unwrap_or_else(|| "public".to_string());
            // Also parse full config for project etc? We don't need fully, just return None config with dist.
            // For simplicity, parse OrandaConfig as well (without deny_unknown_fields for top)
            let full: Result<OrandaConfig, _> = serde_json::from_str(&content);
            match full {
                Ok(cfg) => {
                    let dist2 = cfg.build.as_ref().and_then(|b| b.dist_dir.clone()).unwrap_or(dist);
                    Ok((Some(cfg), dist2))
                }
                Err(_) => {
                    // Use dist from top
                    Ok((None, dist))
                }
            }
        }
        Err(e) => {
            // Parse error
            let msg = "failed to parse JSON";
            let cause = e.to_string(); // e.g., "key must be a string at line 1 column 3"
            // need to compute offset and line/col for diagnostic json
            // e.line() and e.column()
