            std::process::exit(255);
        }
    }
}

fn compute_offset(content: &str, line: usize, column: usize) -> usize {
    // line and column are 1-indexed
    let mut offset = 0;
    let mut current_line = 1;
    for (idx, ch) in content.char_indices() {
        if current_line == line {
            // check column
            // column is byte column? serde_json counts columns as characters? Usually bytes? We'll approximate.
            // We need to count characters in this line up to column-1
            let line_start = offset;
            // Find line content
            // Instead, iterate line by line
            break;
        }
        if ch == '\n' {
            current_line += 1;
        }
        offset = idx + ch.len_utf8();
    }
    // Simpler: split lines
    let lines: Vec<&str> = content.lines().collect();
    let mut off = 0;
    for (i, l) in lines.iter().enumerate() {
        let line_no = i + 1;
        if line_no == line {
            // column is 1-indexed, so offset is off + column -1
            // but column counts bytes? Assume char count.
            // For simplicity, use column-1 as byte offset in line (since ascii)
            return off + column - 1;
        }
        off += l.len() + 1; // +1 for newline
    }
    off
}

