fn wrap_cause(cause: &str) -> Vec<String> {
    // If cause length <= 100, return single
    // If longer, split at last comma before 100 or at space.
    if cause.len() <= 100 {
        return vec![cause.to_string()];
    }
    // Find split position: look for ", " before 100
