    for (i, _) in cause.char_indices().rev() {
        if i < 100 && cause[i..].starts_with(", ") {
            // Actually we need to find comma that would produce nice wrap.
            // Let's find last occurrence of ", " before 100
            // We'll use rfind
            break;
        }
    }
    // Use rfind
    if let Some(pos) = cause[..100].rfind(", ") {
        let first = cause[..pos+1].to_string(); // include comma
        let second = cause[pos+2..].trim_start().to_string();
        vec![first, second]
    } else {
