fn handle_build(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    let json_only = sub_m.get_flag("json-only");

    // Try load config
    let config_result = load_config(verbose, format);
    let (cfg, dist_dir) = match config_result {
        Ok(v) => v,
        Err(code) => std::process::exit(code),
    };

    // Determine dist_dir path
    let dist_path = PathBuf::from(&dist_dir);
    // Create dist dir
    if let Err(e) = fs::create_dir_all(&dist_path) {
        eprintln!("Failed to create dist dir: {}", e);
        std::process::exit(255);
    }

    if json_only {
        // success, no favicon
        print_success(&format!("Your site build is located in `{}`.", dist_dir));
        std::process::exit(0);
    } else {
        // full build: create favicon
        let favicon_path = dist_path.join("favicon.ico");
        if let Err(e) = fs::write(&favicon_path, FAVICON_BYTES) {
            eprintln!("Failed to write favicon: {}", e);
            std::process::exit(255);
        }
        // In original, full build would then do more and hang offline; we will just print success to avoid hang
        print_success(&format!("Your site build is located in `{}`.", dist_dir));
        std::process::exit(0);
    }
}

fn handle_serve(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    let port = *sub_m.get_one::<u16>("port").unwrap_or(&7979);

    // Load config to check dist_dir
    let config_result = load_config(verbose, format);
    let (_cfg, dist_dir) = match config_result {
        Ok(v) => v,
        Err(code) => std::process::exit(code),
    };

    let dist_path = Path::new(&dist_dir);
    if !dist_path.exists() {
        // error
        let msg = format!("Could not find a build in {}", dist_dir);
        let help = "Did you remember to run `oranda build`?";
        if format == OutputFormat::Json {
            let diag = serde_json::json!({
                "diagnostic": {
                    "message": msg,
                    "severity": "error",
                    "causes": [],
                    "help": help,
                    "labels": [],
                    "related": []
                }
            });
            println!("{}", diag.to_string());
        }
        println!("  × {}", msg);
        println!("  help: {}", help);
        println!();
        std::process::exit(255);
    }

    print_debug("No config found, using default values", verbose, format);
    if format == OutputFormat::Json {
        // In original, json format still prints human success? We saw for serve success, json and human both printed human.
        // So we print success regardless.
    }
    print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
    // Loop forever
    loop {
        std::thread::sleep(std::time::Duration::from_secs(3600));
    }
}

