                let offset = compute_offset(&content, line, column);
                let filename = "./oranda.json";
                let diag = serde_json::json!({
                    "diagnostic": {
                        "message": msg,
                        "severity": "error",
                        "causes": [cause.clone()],
                        "filename": filename,
                        "labels": [{"span": {"offset": offset, "length": 1}}],
                        "related": []
                    }
                });
                if format == OutputFormat::Json {
                    println!("{}", diag.to_string());
                }
                println!("  × {}", msg);
                let wrapped = wrap_cause(&cause);
                for (i, part) in wrapped.iter().enumerate() {
                    if i == 0 {
                        println!("  ╰─▶ {}", part);
                    } else {
                        println!("      {}", part);
                    }
                }
                // For simplicity, print snippet minimal
                let lines: Vec<&str> = content.lines().collect();
                let start = if line > 1 { line - 1 } else { 1 };
                let end = if line + 1 <= lines.len() { line + 1 } else { lines.len() };
                println!("   ╭─[{}:{}:1]", filename, start);
                for ln in start..=end {
                    if ln >=1 && ln <= lines.len() {
                        println!("{:2} │ {}", ln, lines[ln-1]);
                        if ln == line {
                            // underline
                            let col = column;
                            // prefix 5 + col-1 spaces after "   ·"
                            let spaces = 5 + col - 1 - 4;
                            if spaces > 0 {
                                println!("   ·{}{}", " ".repeat(spaces), "─");
                            } else {
                                println!("   ·   ─");
                            }
                        }
                    }
                }
                println!("   ╰────");
                println!();
                std::process::exit(255);
            }
        }
        // If build succeeds, print success? Original would print success for build located? But dev without no-first-build original hangs before server success, not printing build success? Let's check.
        // We will skip printing build success to mimic original hang pre-success? But we need to print something? Actually original full build would print success after build? In dev, after first build, it would then start server.
        // For simplicity, we will not print build success, just continue to server.
    }

    // Now start file server (if dist exists, else panic as original)
    // Determine dist_dir
    let dist_dir = {
        if has_config {
            let content = fs::read_to_string(config_path).unwrap_or_default();
            if let Ok(top) = serde_json::from_str::<TopLevel>(&content) {
                top.build.and_then(|b| b.dist_dir).unwrap_or_else(|| "public".to_string())
            } else {
                "public".to_string()
            }
        } else {
            "public".to_string()
        }
    };
    let dist_path = Path::new(&dist_dir);
    if !dist_path.exists() && no_first_build {
        // Original panicked with BuildNotFound
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        // Then panic
        let msg = "oranda panicked.";
        let cause1 = "at src/commands/dev.rs:131:62";
        let cause2 = format!("called `Result::unwrap()` on an `Err` value: BuildNotFound {{ dist_dir: \"{}\" }}", dist_dir);
        let help = "set the `RUST_BACKTRACE=1` environment variable to display a backtrace.";
        if format == OutputFormat::Json {
            let diag = serde_json::json!({
                "diagnostic": {
                    "message": msg,
                    "severity": "error",
                    "causes": [cause1, cause2],
                    "help": help,
                    "labels": [],
                    "related": []
                }
            });
            println!("{}", diag.to_string());
        }
        println!("  × {}", msg);
        println!("  ├─▶ {}", cause1);
        println!("  ╰─▶ {}", cause2);
        println!("  help: {}", help);
        println!();
        // Loop to keep process alive as original did (it printed success then panic but stayed running? In earlier logs, after panic it still had EXIT 124 due to timeout, not 255. Actually it printed success then panic and continued? The timeout killed it. So panic does not exit? In original, after panic it still kept running (server). So we should loop after printing panic, not exit.
        loop {
            std::thread::sleep(std::time::Duration::from_secs(3600));
        }
    }

    // If dist exists and no_first_build, print success and loop
    if dist_path.exists() {
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        loop {
            std::thread::sleep(std::time::Duration::from_secs(3600));
        }
    } else {
        // no dist and !no_first_build: we already did first build (which would create dist). But our build creates dist, so dist should exist now.
        // For simplicity, create dist with favicon if not exists
        let _ = fs::create_dir_all(&dist_path);
        let _ = fs::write(dist_path.join("favicon.ico"), FAVICON_BYTES);
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        loop {
            std::thread::sleep(std::time::Duration::from_secs(3600));
        }
    }
}

fn handle_generate(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    // Check if site-path and output-path options are provided at generate level or ci level
    // For generate, we need to handle subcommand ci
    match sub_m.subcommand() {
        Some(("ci", ci_m)) => {
            // Combine args: need to get output-path and site-path from either parent or child
            // Parent generate args are in sub_m, child in ci_m
            let site_path_parent = sub_m.get_one::<String>("site-path").cloned();
            let output_path_parent = sub_m.get_one::<String>("output-path").cloned();
            let site_path_child = ci_m.get_one::<String>("site-path").cloned();
            let output_path_child = ci_m.get_one::<String>("output-path").cloned();
            let site_path = site_path_child.or(site_path_parent);
            let output_path = output_path_child.or(output_path_parent);
            let ci_type = ci_m.get_one::<String>("ci").unwrap().as_str();

            handle_generate_ci(site_path, output_path, ci_type, verbose, format);
        }
        _ => {
            // No subcommand, clap should have errored, but if we reach here, print help error similar to clap
            // Clap already handles, but we can print
            // Use clap's error handling? We'll just exit with 2 and print message as original does
            eprintln!("error: 'executable generate' requires a subcommand but one was not provided");
            eprintln!("  [subcommands: ci, help]");
            eprintln!();
            eprintln!("Usage: executable generate [OPTIONS] <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

