    #[derive(Debug)]
    pub enum Stream {
        Stdin,
        Stdout,
        Stderr,
    }
    pub fn is(stream: Stream) -> bool {
        // Use IsTerminal trait
        use std::io::IsTerminal;
        match stream {
            Stream::Stdin => std::io::stdin().is_terminal(),
            Stream::Stdout => std::io::stdout().is_terminal(),
            Stream::Stderr => std::io::stderr().is_terminal(),
        }
    }
}
