use clap::{Command, Arg, ArgAction, value_parser};
use std::path::{Path, PathBuf};
use std::fs;
use serde::Deserialize;

const VERSION: &str = "0.6.5";
const FAVICON_BYTES: &[u8] = include_bytes!("../favicon.ico");

fn main() {
    let mut cmd = build_cli();
    let matches = cmd.clone().get_matches();

    let verbose = matches.get_flag("verbose");
    let output_format_str = matches.get_one::<String>("output-format").unwrap().as_str();
    let output_format = match output_format_str {
        "json" => OutputFormat::Json,
        _ => OutputFormat::Human,
    };

    match matches.subcommand() {
        Some(("build", sub_m)) => {
            handle_build(sub_m, verbose, output_format);
        }
        Some(("dev", sub_m)) => {
            handle_dev(sub_m, verbose, output_format);
        }
        Some(("serve", sub_m)) => {
            handle_serve(sub_m, verbose, output_format);
        }
        Some(("generate", sub_m)) => {
            handle_generate(sub_m, verbose, output_format);
        }
        _ => {
            let _ = cmd.print_help();
            println!();
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum OutputFormat {
    Human,
    Json,
}

fn build_cli() -> Command {
    Command::new("oranda")
        .bin_name("executable")
        .version(VERSION)
        .about("🎁 generate beautiful landing pages for your projects")
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .global(true)
                .action(ArgAction::SetTrue)
                .help("Whether to output more detailed debug information")
                .help_heading("GLOBAL OPTIONS"),
        )
        .arg(
            Arg::new("output-format")
                .long("output-format")
                .global(true)
                .value_name("OUTPUT_FORMAT")
                .default_value("human")
                .value_parser(["human", "json"])
                .help("The format of the output")
                .help_heading("GLOBAL OPTIONS"),
        )
        .subcommand(
            Command::new("build")
                .about("Build an oranda site")
                .arg(
                    Arg::new("json-only")
                        .long("json-only")
                        .action(ArgAction::SetTrue)
                        .help("Only build the artifacts JSON file (if applicable) and other files that may be used to support it, such as installer source files"),
                ),
        )
        .subcommand(
            Command::new("dev")
                .about("Start a local development server that recompiles your oranda site if a file changes")
                .arg(
                    Arg::new("port")
                        .long("port")
                        .value_name("PORT")
                        .value_parser(value_parser!(u16))
                        .help("The port for the file server to be launched on"),
                )
                .arg(
                    Arg::new("no-first-build")
                        .long("no-first-build")
                        .action(ArgAction::SetTrue)
                        .help("Skip the first build before starting to watch for changes"),
                )
                .arg(
                    Arg::new("include-paths")
                        .short('i')
                        .long("include-paths")
                        .value_name("INCLUDE_PATHS")
                        .action(ArgAction::Append)
                        .help("List of extra paths to watch"),
                ),
        )
        .subcommand(
            Command::new("serve")
                .about("Start a file server to access your oranda site in a browser")
                .arg(
                    Arg::new("port")
                        .long("port")
                        .value_name("PORT")
                        .default_value("7979")
                        .value_parser(value_parser!(u16))
                        .help(""),
                ),
        )
        .subcommand(
            Command::new("generate")
                .about("Generate infrastructure files for oranda sites")
                .arg(
                    Arg::new("output-path")
                        .short('o')
                        .long("output-path")
                        .value_name("OUTPUT_PATH")
                        .help("Path to the output file"),
                )
                .arg(
                    Arg::new("site-path")
                        .short('s')
                        .long("site-path")
                        .value_name("SITE_PATH")
                        .help("Path to your oranda site"),
                )
                .subcommand(
                    Command::new("ci")
                        .about("Generates a CI file that can be used to deploy your site")
                        .arg(
                            Arg::new("ci")
                                .long("ci")
                                .value_name("CI")
                                .default_value("github")
                                .value_parser(["github"])
                                .help("What CI to generate a file for"),
                        )
                        .arg(
                            Arg::new("output-path")
                                .short('o')
                                .long("output-path")
                                .value_name("OUTPUT_PATH")
                                .help("Path to the output file"),
                        )
                        .arg(
                            Arg::new("site-path")
                                .short('s')
                                .long("site-path")
                                .value_name("SITE_PATH")
                                .help("Path to your oranda site"),
                        ),
                ),
        )
}

