fn main() {
    let args: Vec<String> = env::args().collect();

    // Custom help handling: we need to detect -h/--help and print appropriate hardcoded help
    // This must happen before clap parsing to ensure exact match.

    // Check for --version / -V globally
    if args.iter().any(|a| a == "--version" || a == "-V") {
        // Check if it's for subcommand? Original prints "oranda 0.6.5" for any --version?
        // Test: /workspace/executable build --version ?
        // That should probably print version as well? Let's test later.
        // For now, handle main version.
        // If subcommand also has --version, it still prints same version? Let's see original behavior for subcommand version?
        // Original: build --version? We didn't test. Let's test quickly after implementing.
        println!("oranda {}", VERSION);
        std::process::exit(0);
    }

    // Help handling
    // We need to parse args to determine which help to show.

    // Cases:
    // executable --help => main long
    // executable -h => main short
    // executable help => main long (help subcommand)
    // executable help build => build long
    // executable help dev => dev long
    // executable help serve => serve long
    // executable help generate => generate long
    // executable help generate ci => genci long
    // executable build --help => build long
    // executable build -h => build short
    // similarly dev, serve, generate, generate ci

    // Also: executable generate --help => generate long
    // executable generate -h => generate short
    // executable generate ci --help => genci long
    // executable generate ci -h => genci short

    // Also: executable build help? That is "build help" as subcommand? Original behavior for "build help" gave error "unexpected argument 'help' found" for build, but for generate, "generate help" is valid (help subcommand). Actually "executable generate help" should show generate help? Let's check captured earlier: we have help for generate via "generate --help", but "generate help" might also show help? In clap, "generate help" is automatically handling.

    // Simplify: we will detect patterns.

    let has_long_help = args.iter().any(|a| a == "--help");
    let has_short_help = args.iter().any(|a| a == "-h");

    if has_long_help || has_short_help {
        let is_long = has_long_help;
        // Determine context
        // Look at args after executable
        // If args contain "build" and not "generate", then build help
        // If "dev", dev help
        // If "serve", serve help
        // If "generate" and "ci", genci help
        // If "generate" alone, generate help
        // Otherwise main help

        // Need to check order
        let args_str = args.join(" ");
        // For simplicity, check if args contain "generate" and "ci" => genci
        if args.contains(&"generate".to_string()) && args.contains(&"ci".to_string()) {
            if is_long {
                print!("{}", HELP_GENCI_LONG);
            } else {
                print!("{}", HELP_GENCI_SHORT);
            }
            std::process::exit(0);
        } else if args.contains(&"generate".to_string()) {
            if is_long {
                print!("{}", HELP_GENERATE_LONG);
            } else {
                print!("{}", HELP_GENERATE_SHORT);
            }
            std::process::exit(0);
        } else if args.contains(&"build".to_string()) {
            if is_long {
                print!("{}", HELP_BUILD_LONG);
            } else {
                print!("{}", HELP_BUILD_SHORT);
            }
            std::process::exit(0);
        } else if args.contains(&"dev".to_string()) {
            if is_long {
                print!("{}", HELP_DEV_LONG);
            } else {
                print!("{}", HELP_DEV_SHORT);
            }
            std::process::exit(0);
        } else if args.contains(&"serve".to_string()) {
            if is_long {
                print!("{}", HELP_SERVE_LONG);
            } else {
                print!("{}", HELP_SERVE_SHORT);
            }
            std::process::exit(0);
        } else {
            // main
            if is_long {
                print!("{}", HELP_MAIN_LONG);
            } else {
                print!("{}", HELP_MAIN_SHORT);
            }
            std::process::exit(0);
        }
    }

    // Check for "help" subcommand without -h/--help
    // e.g., executable help, executable help build, etc.
    if args.len() >= 2 && args[1] == "help" {
        // help subcommand
        if args.len() == 2 {
            print!("{}", HELP_MAIN_LONG);
            std::process::exit(0);
        } else if args.len() == 3 {
            match args[2].as_str() {
                "build" => { print!("{}", HELP_BUILD_LONG); std::process::exit(0); }
                "dev" => { print!("{}", HELP_DEV_LONG); std::process::exit(0); }
                "serve" => { print!("{}", HELP_SERVE_LONG); std::process::exit(0); }
                "generate" => { print!("{}", HELP_GENERATE_LONG); std::process::exit(0); }
                _ => {}
            }
        } else if args.len() == 4 {
            if args[2] == "generate" && args[3] == "ci" {
                print!("{}", HELP_GENCI_LONG);
                std::process::exit(0);
            }
        }
    }

    // Now proceed with clap parsing for actual functionality
    let mut cmd = build_cli();
    let matches = cmd.clone().try_get_matches();

    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // Clap error - print as original does: it prints to stderr? Original prints error to stderr? Let's check: earlier we saw error messages were printed to stderr? Actually we captured with 2>&1, but we also tested separate stdout/stderr and saw error for unknown subcommand printed to stderr? For unknown subcommand, we saw stderr contained error. For build --help, stdout contained help. So clap errors go to stderr and exit 2.
            // We need to replicate clap's default error handling which prints error and usage.
            // e.exit() will print error and exit with code 2
            e.exit();
        }
    };

    let verbose = matches.get_flag("verbose");
    let output_format_str = matches.get_one::<String>("output-format").unwrap().as_str();
    let output_format = match output_format_str {
        "json" => OutputFormat::Json,
        _ => OutputFormat::Human,
    };

    match matches.subcommand() {
        Some(("build", sub_m)) => {
            handle_build(sub_m, verbose, output_format);
        }
        Some(("dev", sub_m)) => {
            handle_dev(sub_m, verbose, output_format);
        }
        Some(("serve", sub_m)) => {
            handle_serve(sub_m, verbose, output_format);
        }
        Some(("generate", sub_m)) => {
            handle_generate(sub_m, verbose, output_format);
        }
        _ => {
            // No subcommand: print help? Original for generate without subcommand prints error: 'executable generate' requires a subcommand...
            // But for main without subcommand, what does original do? Let's test: just executable with no args -> should print help? We haven't tested.
            // Test quickly later.
            let _ = cmd.print_help();
            println!();
        }
    }
}

