fn print_debug(msg: &str, verbose: bool, _format: OutputFormat) {
    if verbose {
        println!("↪ >o_o< DEBUG: {}", msg);
    }
}

fn print_success(msg: &str) {
    println!("✓ >o_o< SUCCESS: {}", msg);
}

fn print_warning(msg: &str) {
    println!("⚠ >o_o< WARNING: {}", msg);
}

