    #[serde(default)]
    marketing: Option<serde_json::Value>,
    #[serde(default)]
    styles: Option<serde_json::Value>,
    #[serde(default)]
    components: Option<serde_json::Value>,
    #[serde(default)]
    workspace: Option<serde_json::Value>,
    #[serde(rename = "$schema")]
