fn main() {
    let args: Vec<String> = env::args().collect();

    if args.iter().any(|a| a == "--version" || a == "-V") {
        println!("oranda {}", VERSION);
        std::process::exit(0);
    }

    let has_long_help = args.iter().any(|a| a == "--help");
    let has_short_help = args.iter().any(|a| a == "-h");

    if has_long_help || has_short_help {
        let is_long = has_long_help;
        if args.contains(&"generate".to_string()) && args.contains(&"ci".to_string()) {
            if is_long { print!("{}", HELP_GENCI_LONG); } else { print!("{}", HELP_GENCI_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"generate".to_string()) {
            if is_long { print!("{}", HELP_GENERATE_LONG); } else { print!("{}", HELP_GENERATE_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"build".to_string()) {
            if is_long { print!("{}", HELP_BUILD_LONG); } else { print!("{}", HELP_BUILD_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"dev".to_string()) {
            if is_long { print!("{}", HELP_DEV_LONG); } else { print!("{}", HELP_DEV_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"serve".to_string()) {
            if is_long { print!("{}", HELP_SERVE_LONG); } else { print!("{}", HELP_SERVE_SHORT); }
            std::process::exit(0);
        } else {
            if is_long { print!("{}", HELP_MAIN_LONG); } else { print!("{}", HELP_MAIN_SHORT); }
            std::process::exit(0);
        }
    }

    if args.len() >= 2 && args[1] == "help" {
        if args.len() == 2 {
            print!("{}", HELP_MAIN_LONG);
            std::process::exit(0);
        } else if args.len() == 3 {
            match args[2].as_str() {
                "build" => { print!("{}", HELP_BUILD_LONG); std::process::exit(0); }
                "dev" => { print!("{}", HELP_DEV_LONG); std::process::exit(0); }
                "serve" => { print!("{}", HELP_SERVE_LONG); std::process::exit(0); }
                "generate" => { print!("{}", HELP_GENERATE_LONG); std::process::exit(0); }
                _ => {}
            }
        } else if args.len() == 4 {
            if args[2] == "generate" && args[3] == "ci" {
                print!("{}", HELP_GENCI_LONG);
                std::process::exit(0);
            }
        }
    }

    let mut cmd = build_cli();
    let matches = cmd.clone().try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    let verbose = matches.get_flag("verbose");
    let output_format_str = matches.get_one::<String>("output-format").unwrap().as_str();
    let output_format = match output_format_str {
        "json" => OutputFormat::Json,
        _ => OutputFormat::Human,
    };

    match matches.subcommand() {
        Some(("build", sub_m)) => { handle_build(sub_m, verbose, output_format); }
        Some(("dev", sub_m)) => { handle_dev(sub_m, verbose, output_format); }
        Some(("serve", sub_m)) => { handle_serve(sub_m, verbose, output_format); }
        Some(("generate", sub_m)) => { handle_generate(sub_m, verbose, output_format); }
        _ => {
            let _ = cmd.print_help();
            println!();
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
