Options:
  -o, --output-path <OUTPUT_PATH>  Path to the output file
  -s, --site-path <SITE_PATH>      Path to your oranda site
  -h, --help                       Print help (see more with '--help')

GLOBAL OPTIONS:
  -v, --verbose                        Whether to output more detailed debug information
      --output-format <OUTPUT_FORMAT>  The format of the output [default: human] [possible values:
                                       human, json]
"#;

const HELP_GENCI_LONG: &str = r#"Generates a CI file that can be used to deploy your site

Usage: executable generate ci [OPTIONS]

Options:
      --ci <CI>
          What CI to generate a file for

          [default: github]

          Possible values:
          - github: Deploy to GitHub Pages using GitHub Actions

  -o, --output-path <OUTPUT_PATH>
          Path to the output file

  -s, --site-path <SITE_PATH>
          Path to your oranda site

  -h, --help
          Print help (see a summary with '-h')

GLOBAL OPTIONS:
  -v, --verbose
          Whether to output more detailed debug information

      --output-format <OUTPUT_FORMAT>
          The format of the output

          [default: human]

          Possible values:
          - human: Human-readable output
          - json:  Machine-readable JSON output
"#;

const HELP_GENCI_SHORT: &str = r#"Generates a CI file that can be used to deploy your site

Usage: executable generate ci [OPTIONS]

Options:
      --ci <CI>                    What CI to generate a file for [default: github] [possible
                                   values: github]
  -o, --output-path <OUTPUT_PATH>  Path to the output file
  -s, --site-path <SITE_PATH>      Path to your oranda site
  -h, --help                       Print help (see more with '--help')

GLOBAL OPTIONS:
  -v, --verbose                        Whether to output more detailed debug information
      --output-format <OUTPUT_FORMAT>  The format of the output [default: human] [possible values:
                                       human, json]
"#;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.iter().any(|a| a == "--version" || a == "-V") {
        println!("oranda {}", VERSION);
        std::process::exit(0);
    }

    let has_long_help = args.iter().any(|a| a == "--help");
    let has_short_help = args.iter().any(|a| a == "-h");

    if has_long_help || has_short_help {
        let is_long = has_long_help;
        if args.contains(&"generate".to_string()) && args.contains(&"ci".to_string()) {
            if is_long { print!("{}", HELP_GENCI_LONG); } else { print!("{}", HELP_GENCI_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"generate".to_string()) {
            if is_long { print!("{}", HELP_GENERATE_LONG); } else { print!("{}", HELP_GENERATE_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"build".to_string()) {
            if is_long { print!("{}", HELP_BUILD_LONG); } else { print!("{}", HELP_BUILD_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"dev".to_string()) {
            if is_long { print!("{}", HELP_DEV_LONG); } else { print!("{}", HELP_DEV_SHORT); }
            std::process::exit(0);
        } else if args.contains(&"serve".to_string()) {
            if is_long { print!("{}", HELP_SERVE_LONG); } else { print!("{}", HELP_SERVE_SHORT); }
            std::process::exit(0);
        } else {
            if is_long { print!("{}", HELP_MAIN_LONG); } else { print!("{}", HELP_MAIN_SHORT); }
            std::process::exit(0);
        }
    }

    if args.len() >= 2 && args[1] == "help" {
        if args.len() == 2 {
            print!("{}", HELP_MAIN_LONG);
            std::process::exit(0);
        } else if args.len() == 3 {
            match args[2].as_str() {
                "build" => { print!("{}", HELP_BUILD_LONG); std::process::exit(0); }
                "dev" => { print!("{}", HELP_DEV_LONG); std::process::exit(0); }
                "serve" => { print!("{}", HELP_SERVE_LONG); std::process::exit(0); }
                "generate" => { print!("{}", HELP_GENERATE_LONG); std::process::exit(0); }
                _ => {}
            }
        } else if args.len() == 4 {
            if args[2] == "generate" && args[3] == "ci" {
                print!("{}", HELP_GENCI_LONG);
                std::process::exit(0);
            }
        }
    }

    // Handle no subcommand: original prints main short help and exit 2
    if args.len() == 1 {
        print!("{}", HELP_MAIN_SHORT);
        std::process::exit(2);
    }

    // Check if main subcommand is generate without subcommand
    // Find generate position
    if let Some(pos) = args.iter().position(|a| a == "generate") {
        // Check if after generate there is no ci and no help flag
        let after = &args[pos+1..];
        let has_ci = after.iter().any(|a| a == "ci" || a == "help" || a.starts_with('-'));
        // Actually if after contains only flags (-o, -s, -v, --output-format) and no ci, then it's missing subcommand
        // Original behavior: generate without subcommand prints generate short help and exit 2
        let has_sub = after.iter().any(|a| a == "ci");
        if !has_sub {
            // Check if after only contains known generate options or empty
            // If no ci, print generate short help
            let only_options = after.iter().all(|a| a.starts_with('-') || a == "help");
            if only_options || after.is_empty() {
                // But need to differentiate: if after contains -h/--help we already handled
                // So this is missing subcommand
                print!("{}", HELP_GENERATE_SHORT);
                std::process::exit(2);
            }
        }
    }

    let mut cmd = build_cli();
    let matches = cmd.clone().try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    let verbose = matches.get_flag("verbose");
    let output_format_str = matches.get_one::<String>("output-format").unwrap().as_str();
    let output_format = match output_format_str {
        "json" => OutputFormat::Json,
        _ => OutputFormat::Human,
    };

    match matches.subcommand() {
        Some(("build", sub_m)) => { handle_build(sub_m, verbose, output_format); }
        Some(("dev", sub_m)) => { handle_dev(sub_m, verbose, output_format); }
        Some(("serve", sub_m)) => { handle_serve(sub_m, verbose, output_format); }
        Some(("generate", sub_m)) => { handle_generate(sub_m, verbose, output_format); }
        _ => {
            print!("{}", HELP_MAIN_SHORT);
            std::process::exit(2);
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum OutputFormat { Human, Json }

fn build_cli() -> Command {
    Command::new("oranda")
        .bin_name("executable")
        .version(VERSION)
        .about("🎁 generate beautiful landing pages for your projects")
        // Keep help flag enabled so clap suggests --help
        .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
        .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
        .subcommand(
            Command::new("build").about("Build an oranda site")
                .arg(Arg::new("json-only").long("json-only").action(ArgAction::SetTrue).help("Only build the artifacts JSON file (if applicable) and other files that may be used to support it, such as installer source files"))
                .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
                .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
        )
        .subcommand(
            Command::new("dev").about("Start a local development server that recompiles your oranda site if a file changes")
                .arg(Arg::new("port").long("port").value_name("PORT").value_parser(value_parser!(u16)).help("The port for the file server to be launched on"))
                .arg(Arg::new("no-first-build").long("no-first-build").action(ArgAction::SetTrue).help("Skip the first build before starting to watch for changes"))
                .arg(Arg::new("include-paths").short('i').long("include-paths").value_name("INCLUDE_PATHS").action(ArgAction::Append).help("List of extra paths to watch"))
                .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
                .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
        )
        .subcommand(
            Command::new("serve").about("Start a file server to access your oranda site in a browser")
                .arg(Arg::new("port").long("port").value_name("PORT").default_value("7979").value_parser(value_parser!(u16)).help(""))
                .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
                .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
        )
        .subcommand(
            Command::new("generate").about("Generate infrastructure files for oranda sites")
                .arg(Arg::new("output-path").short('o').long("output-path").value_name("OUTPUT_PATH").help("Path to the output file"))
                .arg(Arg::new("site-path").short('s').long("site-path").value_name("SITE_PATH").help("Path to your oranda site"))
                .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
                .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
                .subcommand(
                    Command::new("ci").about("Generates a CI file that can be used to deploy your site")
                        .arg(Arg::new("ci").long("ci").value_name("CI").default_value("github").value_parser(["github"]).help("What CI to generate a file for"))
                        .arg(Arg::new("output-path").short('o').long("output-path").value_name("OUTPUT_PATH").help("Path to the output file"))
                        .arg(Arg::new("site-path").short('s').long("site-path").value_name("SITE_PATH").help("Path to your oranda site"))
                        .arg(Arg::new("verbose").short('v').long("verbose").global(true).action(ArgAction::SetTrue).help("Whether to output more detailed debug information").help_heading("GLOBAL OPTIONS"))
                        .arg(Arg::new("output-format").long("output-format").global(true).value_name("OUTPUT_FORMAT").default_value("human").value_parser(["human","json"]).help("The format of the output").help_heading("GLOBAL OPTIONS"))
                )
        )
}

fn print_debug(msg: &str, verbose: bool, _format: OutputFormat) {
    if verbose { println!("↪ >o_o< DEBUG: {}", msg); }
}
fn print_success(msg: &str) { println!("✓ >o_o< SUCCESS: {}", msg); }
fn print_warning(msg: &str) { println!("⚠ >o_o< WARNING: {}", msg); }

#[derive(Debug, Deserialize)]
struct OrandaConfig {
    #[serde(default)] project: Option<ProjectConfig>,
    #[serde(default)] build: Option<BuildConfig>,
    #[serde(default)] marketing: Option<serde_json::Value>,
    #[serde(default)] styles: Option<serde_json::Value>,
    #[serde(default)] components: Option<serde_json::Value>,
    #[serde(default)] workspace: Option<serde_json::Value>,
    #[serde(rename = "$schema")] #[serde(default)] schema: Option<serde_json::Value>,
}
#[derive(Debug, Deserialize)]
struct ProjectConfig { name: Option<String>, #[serde(default)] repository: Option<String>, }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct BuildConfig {
    #[serde(default)] dist_dir: Option<String>,
    #[serde(default)] static_dir: Option<String>,
    #[serde(default)] path_prefix: Option<String>,
    #[serde(default)] additional_pages: Option<serde_json::Value>,
}
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct TopLevel {
    #[serde(default)] project: Option<serde_json::Value>,
    #[serde(default)] build: Option<BuildConfig>,
    #[serde(default)] marketing: Option<serde_json::Value>,
    #[serde(default)] styles: Option<serde_json::Value>,
    #[serde(default)] components: Option<serde_json::Value>,
    #[serde(default)] workspace: Option<serde_json::Value>,
    #[serde(rename = "$schema")] #[serde(default)] schema: Option<serde_json::Value>,
}

fn json_escape(s: &str) -> String { serde_json::to_string(s).unwrap() }

fn format_diagnostic_message(message: &str, severity: &str, causes: &[String], filename: Option<&str>, help: Option<&str>, labels: &[(usize,usize)]) -> String {
    let mut out = String::new();
    out.push_str("{\"diagnostic\": {");
    out.push_str(&format!("\"message\": {}", json_escape(message)));
    out.push_str(&format!(",\"severity\": {}", json_escape(severity)));
    out.push_str(",\"causes\": [");
    for (i,c) in causes.iter().enumerate() { if i>0 { out.push(','); } out.push_str(&json_escape(c)); }
    out.push(']');
    if let Some(fname) = filename { out.push_str(&format!(",\"filename\": {}", json_escape(fname))); }
    if let Some(h) = help { out.push_str(&format!(",\"help\": {}", json_escape(h))); }
    out.push_str(",\"labels\": [");
    for (i,(off,len)) in labels.iter().enumerate() {
        if i>0 { out.push(','); }
        out.push_str(&format!("{{\"span\": {{\"offset\": {},\"length\": {}}}}}", off, len));
    }
    out.push_str("]");
    out.push_str(",\"related\": []");
    out.push_str("}}");
    out
}
fn format_diagnostic_with_filename(message: &str, causes: &[String], filename: &str, offset: usize, len: usize) -> String {
    format_diagnostic_message(message, "error", causes, Some(filename), None, &[(offset,len)])
}
fn format_diagnostic_with_help(message: &str, causes: &[String], help: &str) -> String {
    format_diagnostic_message(message, "error", causes, None, Some(help), &[])
}
fn format_diagnostic_panic(message: &str, causes: &[String], help: &str) -> String {
    format_diagnostic_message(message, "error", causes, None, Some(help), &[])
}

fn load_config(verbose: bool, format: OutputFormat) -> Result<(Option<OrandaConfig>, String), i32> {
    let path = Path::new("./oranda.json");
    if !path.exists() {
        print_debug("No config found, using default values", verbose, format);
        return Ok((None, "public".to_string()));
    }
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_e) => std::process::exit(255),
    };
    let result: Result<TopLevel, serde_json::Error> = serde_json::from_str(&content);
    match result {
        Ok(top) => {
            let dist = top.build.and_then(|b| b.dist_dir).unwrap_or_else(|| "public".to_string());
            let full: Result<OrandaConfig, _> = serde_json::from_str(&content);
            match full {
                Ok(cfg) => {
                    let dist2 = cfg.build.as_ref().and_then(|b| b.dist_dir.clone()).unwrap_or(dist);
                    Ok((Some(cfg), dist2))
                }
                Err(_) => Ok((None, dist)),
            }
        }
        Err(e) => {
            let msg = "failed to parse JSON";
            let cause = e.to_string();
            let line = e.line();
            let column = e.column();
            let offset = compute_offset(&content, line, column);
            let filename = "./oranda.json";
            if format == OutputFormat::Json {
                let diag = format_diagnostic_with_filename(msg, &[cause.clone()], filename, offset, 1);
                println!("{}", diag);
            }
            println!("  × {}", msg);
            let wrapped = wrap_cause(&cause);
            for (i, part) in wrapped.iter().enumerate() {
                if i == 0 { println!("  ╰─▶ {}", part); } else { println!("      {}", part); }
            }
            let lines: Vec<&str> = content.lines().collect();
            let total = lines.len();
            if total > 0 {
                let start = if line > 1 { line - 1 } else { 1 };
                let end = if line + 1 <= total { line + 1 } else { total };
                println!("   ╭─[{}:{}:1]", filename, start);
                for ln in start..=end {
                    if ln >=1 && ln <= total {
                        let line_content = lines[ln-1];
                        println!("{:2} │ {}", ln, line_content);
                        if ln == line {
                            let prefix_len = 5;
                            let spaces_needed = if prefix_len + column > 4 { prefix_len + column - 1 - 4 } else { 3 };
                            println!("   ·{}{}", " ".repeat(spaces_needed), "─");
                        }
                    }
                }
                println!("   ╰────");
            }
            println!();
            std::process::exit(255);
        }
    }
}

fn compute_offset(content: &str, line: usize, column: usize) -> usize {
    let lines: Vec<&str> = content.lines().collect();
    let mut off = 0;
    for (i, l) in lines.iter().enumerate() {
        let line_no = i + 1;
        if line_no == line { return off + column - 1; }
        off += l.len() + 1;
    }
    off
}
fn wrap_cause(cause: &str) -> Vec<String> {
    if cause.len() <= 100 { return vec![cause.to_string()]; }
    if let Some(pos) = cause[..100].rfind(", ") {
        let first = cause[..pos+1].to_string();
        let second = cause[pos+2..].trim_start().to_string();
        vec![first, second]
    } else {
        vec![cause[..100].to_string(), cause[100..].to_string()]
    }
}

fn handle_build(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    let json_only = sub_m.get_flag("json-only");
    let (_cfg, dist_dir) = match load_config(verbose, format) {
        Ok(v) => v,
        Err(code) => std::process::exit(code),
    };
    let dist_path = PathBuf::from(&dist_dir);
    let _ = fs::create_dir_all(&dist_path);
    if !json_only {
        let favicon_path = dist_path.join("favicon.ico");
        let _ = fs::write(&favicon_path, FAVICON_BYTES);
    }
    print_success(&format!("Your site build is located in `{}`.", dist_dir));
    std::process::exit(0);
}

fn handle_serve(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    let port = *sub_m.get_one::<u16>("port").unwrap_or(&7979);
    let (_cfg, dist_dir) = match load_config(verbose, format) {
        Ok(v) => v,
        Err(code) => std::process::exit(code),
    };
    let dist_path = Path::new(&dist_dir);
    if !dist_path.exists() {
        let msg = format!("Could not find a build in {}", dist_dir);
        let help = "Did you remember to run `oranda build`?";
        if format == OutputFormat::Json {
            let diag = format_diagnostic_with_help(&msg, &[], help);
            println!("{}", diag);
        }
        println!("  × {}", msg);
        println!("  help: {}", help);
        println!();
        std::process::exit(255);
    }
    print_debug("No config found, using default values", verbose, format);
    print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
    loop { std::thread::sleep(std::time::Duration::from_secs(3600)); }
}

fn handle_dev(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    let no_first_build = sub_m.get_flag("no-first-build");
    let include_paths: Vec<String> = sub_m.get_many::<String>("include-paths").map(|v| v.cloned().collect()).unwrap_or_default();
    let port = sub_m.get_one::<u16>("port").map(|p| *p).unwrap_or(7979);
    let config_path = Path::new("./oranda.json");
    let has_config = config_path.exists();
    let mut watched: Vec<String> = Vec::new();
    if has_config { watched.push("oranda.json".to_string()); }
    for p in &include_paths { watched.push(p.clone()); }
    if !has_config { print_debug("No config found, using default values", verbose, format); }
    println!("↪ >o_o< INFO: Found {} paths to watch, starting watch...", watched.len());
    if verbose {
        let json_array = serde_json::to_string(&watched).unwrap_or("[]".to_string());
        println!("↪ >o_o< DEBUG: Files watched: {}", json_array);
    }
    if !no_first_build {
        if !has_config {
            print_debug("No config found, using default values", verbose, format);
        } else {
            let content = fs::read_to_string(config_path).unwrap_or_default();
            let result: Result<TopLevel, _> = serde_json::from_str(&content);
            if let Err(e) = result {
                let msg = "failed to parse JSON";
                let cause = e.to_string();
                let line = e.line();
                let column = e.column();
                let offset = compute_offset(&content, line, column);
                let filename = "./oranda.json";
                if format == OutputFormat::Json {
                    let diag = format_diagnostic_with_filename(msg, &[cause.clone()], filename, offset, 1);
                    println!("{}", diag);
                }
                println!("  × {}", msg);
                let wrapped = wrap_cause(&cause);
                for (i, part) in wrapped.iter().enumerate() {
                    if i == 0 { println!("  ╰─▶ {}", part); } else { println!("      {}", part); }
                }
                let lines: Vec<&str> = content.lines().collect();
                let total = lines.len();
                if total > 0 {
                    let start = if line > 1 { line - 1 } else { 1 };
                    let end = if line + 1 <= total { line + 1 } else { total };
                    println!("   ╭─[{}:{}:1]", filename, start);
                    for ln in start..=end {
                        if ln >=1 && ln <= total {
                            println!("{:2} │ {}", ln, lines[ln-1]);
                            if ln == line {
                                let prefix_len = 5;
                                let spaces_needed = if prefix_len + column > 4 { prefix_len + column - 1 - 4 } else { 3 };
                                println!("   ·{}{}", " ".repeat(spaces_needed), "─");
                            }
                        }
                    }
                    println!("   ╰────");
                }
                println!();
                std::process::exit(255);
            }
        }
    }
    let dist_dir = {
        if has_config {
            let content = fs::read_to_string(config_path).unwrap_or_default();
            if let Ok(top) = serde_json::from_str::<TopLevel>(&content) {
                top.build.and_then(|b| b.dist_dir).unwrap_or_else(|| "public".to_string())
            } else { "public".to_string() }
        } else { "public".to_string() }
    };
    let dist_path = Path::new(&dist_dir);
    if !dist_path.exists() && no_first_build {
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        let msg = "oranda panicked.";
        let cause1 = "at src/commands/dev.rs:131:62";
        let cause2 = format!("called `Result::unwrap()` on an `Err` value: BuildNotFound {{ dist_dir: \"{}\" }}", dist_dir);
        let help = "set the `RUST_BACKTRACE=1` environment variable to display a backtrace.";
        if format == OutputFormat::Json {
            let diag = format_diagnostic_panic(msg, &[cause1.to_string(), cause2.clone()], help);
            println!("{}", diag);
        }
        println!("  × {}", msg);
        println!("  ├─▶ {}", cause1);
        println!("  ╰─▶ {}", cause2);
        println!("  help: {}", help);
        println!();
        loop { std::thread::sleep(std::time::Duration::from_secs(3600)); }
    }
    if dist_path.exists() {
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        loop { std::thread::sleep(std::time::Duration::from_secs(3600)); }
    } else {
        let _ = fs::create_dir_all(&dist_path);
        let _ = fs::write(dist_path.join("favicon.ico"), FAVICON_BYTES);
        print_success(&format!("Your project is available at: http://127.0.0.1:{}/", port));
        loop { std::thread::sleep(std::time::Duration::from_secs(3600)); }
    }
}

fn handle_generate(sub_m: &clap::ArgMatches, verbose: bool, format: OutputFormat) {
    match sub_m.subcommand() {
        Some(("ci", ci_m)) => {
            let site_path_parent = sub_m.get_one::<String>("site-path").cloned();
            let output_path_parent = sub_m.get_one::<String>("output-path").cloned();
            let site_path_child = ci_m.get_one::<String>("site-path").cloned();
            let output_path_child = ci_m.get_one::<String>("output-path").cloned();
            let site_path = site_path_child.or(site_path_parent);
            let output_path = output_path_child.or(output_path_parent);
            let ci_type = ci_m.get_one::<String>("ci").unwrap().as_str();
            handle_generate_ci(site_path, output_path, ci_type, verbose, format);
        }
        _ => {
            print!("{}", HELP_GENERATE_SHORT);
            std::process::exit(2);
        }
    }
}

fn handle_generate_ci(site_path_opt: Option<String>, output_path_opt: Option<String>, _ci_type: &str, _verbose: bool, format: OutputFormat) {
    println!("↪ >o_o< INFO: Generating a CI deploy workflow for your site...");
    let is_tty = atty::is(atty::Stream::Stdin);
    if !is_tty {
        let msg = "oranda panicked.";
        let causes = vec!["at src/generate.rs:56:14".to_string(), "Error while prompting!: NotTTY".to_string()];
        let help = "set the `RUST_BACKTRACE=1` environment variable to display a backtrace.";
        if format == OutputFormat::Json {
            let diag = format_diagnostic_panic(msg, &causes, help);
            println!("{}", diag);
        }
        println!("  × {}", msg);
        println!("  ├─▶ {}", causes[0]);
        println!("  ╰─▶ {}", causes[1]);
        println!("  help: {}", help);
        println!();
        std::process::exit(255);
    }
    use std::io::{self, Write};
    fn ask_yes_no(prompt: &str, default_yes: bool, extra: Option<&str>) -> bool {
        print!("? >o_o< {} ", prompt);
        io::stdout().flush().unwrap();
        if let Some(ex) = extra {
            println!();
            println!("{}", ex);
        }
        let mut input = String::new();
        let _ = io::stdin().read_line(&mut input);
        let trimmed = input.trim().to_lowercase();
        let result = if trimmed.is_empty() {
            default_yes
        } else if trimmed == "y" || trimmed == "yes" { true } else if trimmed == "n" || trimmed == "no" { false } else { default_yes };
        let answer_str = if result { "Yes" } else { "No" };
        println!("> {} {}", prompt, answer_str);
        result
    }
    let include_hyperlink = ask_yes_no("Do you want to include a tool for checking generated hyperlinks? (Y/n)", true, Some("[Read more about the link checker tool: https://github.com/untitaker/hyperlink]"));
    let use_latest = ask_yes_no("Do you want to always use the latest version of oranda? (y/N)", false, Some("[Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!]"));
    let append_gitignore = ask_yes_no("Would you like to append the default destination directory (`public`) to your .gitignore file? (y/N)", false, None);
    let site_path = site_path_opt.unwrap_or_else(|| ".".to_string());
    let site_path_buf = PathBuf::from(&site_path);
    let output_path = if let Some(p) = output_path_opt { PathBuf::from(p) } else { PathBuf::from(".github/workflows/web.yml") };
    let ci_content = generate_ci_content(&site_path_buf, include_hyperlink, use_latest);
    if let Some(parent) = output_path.parent() { let _ = fs::create_dir_all(parent); }
    let _ = fs::write(&output_path, ci_content);
    if append_gitignore {
        let gitignore_path = PathBuf::from(".gitignore");
        let entry = "# Generated by `oranda generate ci`\npublic/\n";
        if gitignore_path.exists() {
            let existing = fs::read_to_string(&gitignore_path).unwrap_or_default();
            if existing.trim() == entry.trim() {
                print_warning("File exists and is identical, aborting...");
            } else {
                let mut new_content = existing;
                if !new_content.ends_with('\n') { new_content.push('\n'); }
                new_content.push('\n');
                new_content.push_str(entry);
                let _ = fs::write(&gitignore_path, new_content);
            }
        } else {
            let _ = fs::write(&gitignore_path, entry);
        }
    }
    print_success(&format!("Wrote CI file to \"{}\"", output_path.display()));
    std::process::exit(0);
}

fn generate_ci_content(site_path: &PathBuf, include_hyperlink: bool, use_latest: bool) -> String {
    let installer_version = if use_latest { "latest/download".to_string() } else { "download/v0.6.1".to_string() };
    let cd_part = if site_path == Path::new(".") || site_path.as_os_str().is_empty() { "".to_string() } else { format!("cd {}\n          ", site_path.display()) };
    let hyperlink_steps = if include_hyperlink {
        r#"
      - name: Prepare HTML for link checking
        # untitaker/hyperlink supports no site prefixes, move entire site into
        # a subfolder
        run: mkdir /tmp/public/ && cp -R public /tmp/public/oranda

      - name: Check HTML for broken internal links
        uses: untitaker/hyperlink@0.1.29
        with:
          args: /tmp/public/
      "#.to_string()
    } else { "".to_string() };
    format!(
        r#"# Workflow to build your docs with oranda (and mdbook)
# and deploy them to Github Pages
name: Web

# We're going to push to the gh-pages branch, so we need that permission
permissions:
  contents: write

# What situations do we want to build docs in?
# All of these work independently and can be removed / commented out
# if you don't want oranda/mdbook running in that situation
on:
  # Check that a PR didn't break docs!
  #
  # Note that the "Deploy to Github Pages" step won't run in this mode,
  # so this won't have any side-effects. But it will tell you if a PR
  # completely broke oranda/mdbook. Sadly we don't provide previews (yet)!
  pull_request:

  # Whenever something gets pushed to main, update the docs!
  # This is great for getting docs changes live without cutting a full release.
  #
  # Note that if you're using cargo-dist, this will "race" the Release workflow
  # that actually builds the Github Release that oranda tries to read (and
  # this will almost certainly complete first). As a result you will publish
  # docs for the latest commit but the oranda landing page won't know about
  # the latest release. The workflow_run trigger below will properly wait for
  # cargo-dist, and so this half-published state will only last for ~10 minutes.
  #
  # If you only want docs to update with releases, disable this, or change it to
  # a "release" branch. You can, of course, also manually trigger a workflow run
  # when you want the docs to update.
  push:
    branches:
      - main

  # Whenever a workflow called "Release" completes, update the docs!
  #
  # If you're using cargo-dist, this is recommended, as it will ensure that
  # oranda always sees the latest release right when it's available. Note
  # however that Github's UI is wonky when you use workflow_run, and won't
  # show this workflow as part of any commit. You have to go to the "actions"
  # tab for your repo to see this one running (the gh-pages deploy will also
  # only show up there).
  workflow_run:
    workflows: [ "Release" ]
    types:
      - completed

# Alright, let's do it!
jobs:
  web:
    name: Build and deploy site and docs
    runs-on: ubuntu-latest
    steps:
      # Setup
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0
      - uses: dtolnay/rust-toolchain@stable
      - uses: swatinem/rust-cache@v2

      # If you use any mdbook plugins, here's the place to install them!

      # Install and run oranda (and mdbook)!
      #
      # This will write all output to ./public/ (including copying mdbook's output to there).
      - name: Install and run oranda
        run: |
          curl --proto '=https' --tlsv1.2 -LsSf https://github.com/axodotdev/oranda/releases/{installer_version}/oranda-installer.sh | sh
          {cd_part}oranda build
      {hyperlink_steps}
      # Deploy to our gh-pages branch (creating it if it doesn't exist).
      # The "public" dir that oranda made above will become the root dir
      # of this branch.
      #
      # Note that once the gh-pages branch exists, you must
      # go into repo's settings > pages and set "deploy from branch: gh-pages".
      # The other defaults work fine.
      - name: Deploy to Github Pages
        uses: JamesIves/github-pages-deploy-action@v4.4.1
        # ONLY if we're on main (so no PRs or feature branches allowed!)
        if: ${{ github.ref == 'refs/heads/main' }}
        with:
          branch: gh-pages
          # Gotta tell the action where to find oranda's output
          folder: public
          token: ${{ secrets.GITHUB_TOKEN }}
          single-commit: true
"#,
        installer_version = installer_version,
        cd_part = cd_part,
        hyperlink_steps = hyperlink_steps
    )
}

mod atty {
    pub enum Stream { Stdin, }
    pub fn is(stream: Stream) -> bool {
        use std::io::IsTerminal;
        match stream { Stream::Stdin => std::io::stdin().is_terminal(), }
    }
}
